const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => $(name).all()
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
const settingsOf = (name) => Object.fromEntries(
  rowsOf(name).filter((r) => r.key).map((r) => [r.key, (r.value ?? '').toString().trim()]));
const parseDt = (s) => DateTime.fromISO(String(s || '').trim().replace(' ', 'T'), { setZone: true }).setZone(TZ);
const parseDate = (s) => DateTime.fromISO(String(s || '').trim().slice(0, 10), { zone: TZ });

const input = $('When called').first().json;
const piece = rowsOf('Load piece')[0];
if (!piece) throw new Error(`Piece ${input.piece_id} not found`);
const feedback = (input.feedback || '').toString().trim();
const material = (input.material || '').toString().trim();
if (['published', 'scheduled'].includes(piece.status)) {
  throw new Error(`Piece ${piece.Id} "${piece.title}" is already ${piece.status}; it is not rewritten.`);
}
if (piece.status === 'rejected' && !feedback && !material) {
  throw new Error(`Piece ${piece.Id} "${piece.title}" is rejected; reply to its card with changes to revive it.`);
}
const stamp = DateTime.now().setZone(TZ).toFormat('yyyy-MM-dd HH:mm');
const append = (old, add) => (add ? [old, `[${stamp}] ${add}`].filter(Boolean).join('\n\n') : (old || ''));
return [{
  json: {
    piece,
    feedback_new: feedback,
    feedback: append(piece.feedback, feedback),
    material: append(piece.material, material),
  },
}];

const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => $(name).all()
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
const settingsOf = (name) => Object.fromEntries(
  rowsOf(name).filter((r) => r.key).map((r) => [r.key, (r.value ?? '').toString().trim()]));
const parseDt = (s) => DateTime.fromISO(String(s || '').trim().replace(' ', 'T'), { setZone: true }).setZone(TZ);
const parseDate = (s) => DateTime.fromISO(String(s || '').trim().slice(0, 10), { zone: TZ });

const FRAMEWORK = {
  education: 'Education. Makes the brand the authority on this problem. Open with the problem in the reader\'s own words and what it costs them. Then a clear sequence of 3 to 7 steps or points, each concrete and doable, visibly separated (numbered or one per paragraph). The title does not need to be a list; the body does. Close with what changes when they do this, and a light question or invitation to save. It sets up the offer by teaching what the reader must understand, never by pitching.',
  story: 'Story. Intent, obstacle, resolution: we set out to give you [benefit]; but [problem] got in the way; so we [sacrifice or decision], because giving you [benefit] matters that much. Told as one episode of the brand\'s mission, with a concrete moment, a real tension and the value that was tested. End on what it means for the reader. No selling.',
  offer_launch: 'Sales, offer launch. Open with a hook tied to the reason. Weave in a short story (intent, obstacle, resolution) that leads to the offer. State the offer plainly: product, deal, end date. Give the reason explicitly: why this offer exists now. Say who it is for and what they get, using what the run-up taught. One clear call to action, with the link when there is one.',
  offer_reminder: 'Sales, offer reminder. Shorter than the launch. A new angle: a proof point, an answered objection, or the approaching end date. Restate the offer, the reason and the end date plainly. One clear call to action, with the link when there is one.',
};

const g = $('Guard').first().json;
const piece = g.piece;
const ctx = $('Get context').first().json;
const offer = rowsOf('Load offer')[0] || null;
const series = rowsOf('Load series');
const stories = rowsOf('Load stories');
const at = parseDt(piece.publish_at);
const sales = ['offer_launch', 'offer_reminder'].includes(piece.kind);
const lines = (s) => (s || '').split('\n').filter(Boolean).map((l) => `- ${l}`).join('\n');

const index = series.findIndex((p) => p.Id === piece.Id);
const before = series.slice(0, Math.max(index, 0));
const after = index >= 0 ? series.slice(index + 1) : [];
const seriesText = [
  ...before.map((p, i) => {
    const head = `- ${parseDt(p.publish_at).toFormat('dd/MM')} ${p.kind}: ${p.title}`;
    const recentDraft = i >= before.length - 2 && p.draft ? `\n  Opening of that post: ${p.draft.slice(0, 280).replace(/\n+/g, ' ')}` : '';
    return head + recentDraft;
  }),
  `- ${at.toFormat('dd/MM')} ${piece.kind}: ${piece.title}   <== THIS POST`,
  ...after.map((p) => `- ${parseDt(p.publish_at).toFormat('dd/MM')} ${p.kind}: ${p.title}`),
].join('\n');

const offerText = offer ? [
  `${offer.title}: ${offer.product}, ${offer.offer}.`,
  `Reason (${offer.reason_type}): ${offer.reason}`,
  `Launch ${offer.launch_date}, reminder ${offer.reminder_date}, ends ${offer.ends_on}.${offer.landing_url ? ` Link: ${offer.landing_url}` : ''}`,
  `Must know:\n${lines(offer.must_know)}`,
  `Must feel:\n${lines(offer.must_feel)}`,
].join('\n') : '(no offer linked)';

const facts = [
  `Author's material (true, use it):\n${g.material || '(none)'}`,
  `Story bank (true events you may use):\n${stories.map((s) => `#${s.Id}: ${(s.text || '').toString().slice(0, 800)}`).join('\n') || '(empty)'}`,
  `Brand docs:\n${ctx.brand}`,
].join('\n\n');

const base = [
  `Brand: ${ctx.page_name}. Language of the post: ${ctx.language}.`,
  `Kind: ${piece.kind}. Framework: ${FRAMEWORK[piece.kind] || ''}`,
  sales ? '' : 'This post must not sell: no price, discount, deadline, link or call to buy. It may end with a question, or an invitation to comment or save.',
  '',
  `Offer this post leads toward:\n${offerText}`,
  '',
  `Post: ${piece.title}`,
  `Publishes: ${at.toFormat('cccc dd/MM/yyyy HH:mm')}`,
  `Sets up: ${piece.sets_up || '(not stated)'}`,
  `Brief:\n${piece.brief || ''}`,
  '',
  `The author's change requests (apply every one; newest last):\n${g.feedback || '(none)'}`,
  '',
  `The series leading to the offer (keep continuity, do not repeat what earlier posts said):\n${seriesText}`,
  '',
  `Rules learned from past months:\n${ctx.rules || '(none yet)'}`,
  '',
  `Hooks that did well for similar pages (rhythm only, never copy):\n${ctx.references.map((r) => `- ${r.hook}`).join('\n') || '(none)'}`,
  '',
  facts,
].join('\n');

const previous = g.feedback_new && piece.draft ? piece.draft : '';
const writer_text = previous
  ? `${base}\n\nThe current draft, to rewrite with the author's newest change request:\n<<<\n${previous}\n>>>`
  : base;

return [{
  json: {
    attempt: 1,
    writer_text,
    base,
    facts,
    offer_text: offerText,
    piece,
    sales,
    language: ctx.language,
    landing_url: offer ? offer.landing_url || '' : '',
    ends_on: offer ? offer.ends_on || '' : '',
  },
}];

const parseJson = (s) => {
  const t = String(s || '').replace(/```(?:json)?/gi, '');
  const a = t.indexOf('{');
  const b = t.lastIndexOf('}');
  if (a < 0 || b <= a) throw new Error('no JSON object in the model output');
  return JSON.parse(t.slice(a, b + 1));
};

const state = $('Judge input').last().json;
const draft = state.draft;
// In JSON response mode the chain node returns the parsed object instead of { text }.
let v;
try {
  v = $json.text === undefined ? $json : parseJson($json.text);
} catch (e) {
  v = { fix: 'The check could not be read; tighten the post and follow the framework exactly.' };
}
const arr = (x) => (Array.isArray(x) ? x : x ? [x] : []).map((s) => s.toString().trim()).filter(Boolean);
const checks = ['relevant', 'closer', 'connected', 'structure'];
const violations = arr(v.violations);

// A claim counts as supported only if its quoted source really is in the facts.
const norm = (t) => String(t || '').toLowerCase().normalize('NFC').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
const facts = norm(`${state.facts}
${state.offer_text}`);
const factWords = new Set(facts.split(' '));
const supported = (source) => {
  const src = norm(source);
  if (src.length < 8) return false;
  if (facts.includes(src)) return true;
  const words = src.split(' ').filter((w) => w.length > 1);
  return words.length >= 4 && words.filter((w) => factWords.has(w)).length / words.length >= 0.85;
};
const claims = Array.isArray(v.claims) ? v.claims : [];
const invented = claims
  .filter((c) => c && c.claim && c.general !== true && !supported(c.source))
  .map((c) => c.claim.toString().trim());

// Rules the model tends to miss, checked by code.
if (/(^|\s)#[\p{L}\d_]+/u.test(draft)) violations.push('Contains hashtags.');
if ((draft.match(/\p{Extended_Pictographic}/gu) || []).length > 2) violations.push('More than two emojis.');
if (!state.sales) {
  if (state.landing_url && draft.includes(state.landing_url)) violations.push('Links the offer in a non-sales post.');
  if (/(\d+\s?%|giảm giá|khuyến mãi|ưu đãi|mã giảm|voucher|đăng ký ngay|mua ngay|chốt đơn)/i.test(draft)) violations.push('Mentions a discount or a call to buy in a non-sales post.');
}
if (draft.length < 200) violations.push('Too short to deliver the brief.');

const failed = checks.filter((k) => !(v[k] && v[k].pass === true));
const passed = failed.length === 0 && violations.length === 0 && invented.length === 0;
const mark = (k) => `${v[k] && v[k].pass === true ? '✅' : '❌'} ${k}: ${(v[k] && v[k].why) || 'not judged'}`;
const report = [
  ...checks.map(mark),
  v.connected && v.connected.leads_to ? `Leads to: ${v.connected.leads_to}` : '',
  violations.length ? `❌ rules: ${violations.join(' ')}` : '✅ rules',
  invented.length ? `❌ invented: ${invented.join(' | ')}` : '✅ nothing invented',
].filter(Boolean).join('\n');
const question = (v.question_for_author || '').toString().trim();

if (passed || state.attempt >= 3) {
  return [{ json: { ...state, done: true, passed, report, question, draft } }];
}
const fix = [
  ...failed.map((k) => `${k}: ${(v[k] && v[k].why) || 'failed'}`),
  ...violations,
  ...invented.map((c) => `Remove this claim, or tell it only as far as the facts state it: ${c}`),
  v.fix || '',
].filter(Boolean).map((l) => `- ${l}`).join('\n');
return [{
  json: {
    ...state,
    done: false,
    attempt: state.attempt + 1,
    writer_text: `${state.base}\n\nYour previous draft failed the pre-publish check:\n<<<\n${draft}\n>>>\n\nWrite a new draft that fixes all of this:\n${fix}`,
  },
}];

const newToken = () => Array.from({ length: 24 }, () => 'abcdefghijklmnopqrstuvwxyz0123456789'[Math.floor(Math.random() * 36)]).join('');

const e = $json;
return [{
  json: {
    ...e,
    status: e.passed ? 'awaiting_approval' : 'needs_attention',
    approval_token: newToken(),
    check_report: e.question ? `${e.report}\n❓ ${e.question}` : e.report,
  },
}];

const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => $(name).all()
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
const settingsOf = (name) => Object.fromEntries(
  rowsOf(name).filter((r) => r.key).map((r) => [r.key, (r.value ?? '').toString().trim()]));
const parseDt = (s) => DateTime.fromISO(String(s || '').trim().replace(' ', 'T'), { setZone: true }).setZone(TZ);
const parseDate = (s) => DateTime.fromISO(String(s || '').trim().slice(0, 10), { zone: TZ });

const d = $('Draft fields').first().json;
const p = d.piece;
const at = parseDt(p.publish_at);
const kindLabel = { education: 'Education', story: 'Story', offer_launch: 'Offer launch', offer_reminder: 'Offer reminder' };
const color = { education: 'blue', story: 'purple', offer_launch: 'red', offer_reminder: 'orange' };
const elements = [
  { tag: 'markdown', content: `**Goes out** ${at.toFormat('cccc dd/MM HH:mm')}\n**Sets up:** ${p.sets_up || '-'}` },
  { tag: 'hr' },
  { tag: 'div', text: { tag: 'plain_text', content: d.draft } },
  { tag: 'hr' },
  {
    tag: 'markdown',
    content: (d.passed
      ? `**Pre-publish check passed** (draft ${d.attempt})\n`
      : `**⚠️ Still failing the check after ${d.attempt} drafts.** Approve it anyway, reject it, or reply with what it needs.\n`) + d.check_report,
  },
  {
    tag: 'column_set',
    flex_mode: 'flow',
    columns: [['Approve', 'primary', 'piece_approve'], ['Reject', 'danger', 'piece_reject']].map(([label, type, a]) => ({
      tag: 'column',
      width: 'auto',
      elements: [{
        tag: 'button',
        type,
        text: { tag: 'plain_text', content: label },
        behaviors: [{ type: 'callback', value: { a, id: p.Id, t: d.approval_token } }],
      }],
    })),
  },
  { tag: 'markdown', content: 'Reply to this card with changes or missing facts and I rewrite it.' },
];
return [{
  json: {
    card: {
      schema: '2.0',
      header: {
        title: { tag: 'plain_text', content: `${kindLabel[p.kind] || p.kind} · ${at.toFormat('dd/MM')} · ${p.title}`.slice(0, 100) },
        template: d.passed ? (color[p.kind] || 'blue') : 'grey',
      },
      body: { elements },
    },
    ref: `piece:${p.Id}`,
    purpose: 'draft_card',
  },
}];
